const NINTH_ORIGINAL_URL=new URL("../../../../../seventh-reconciliation/verify-dependencies.mjs",import.meta.url);
import {ninthLeaf,ninthHash,ninthEntry,ninthQuestion,ninthReferenceQuestion,ninthReferenceEntry,ninthIncludes,ninthFragment,ninthSubstantiveIncludes,ninthSourceText,ninthSourceHash,ninthRegistryBefore,ninthEntryHash,ninthKeyIncludes,ninthKeyHash,ninthKeyFragment,ninthKeyQuestion} from '../../../../verify-reference.mjs';
import assert from 'node:assert/strict';import fs from 'node:fs';import {createHash} from 'node:crypto';
import {eighthEntry,eighthSourceText,eighthSourceHash} from '../eighth-reconciliation/verify-dependencies.mjs';
const sha=s=>createHash('sha256').update(s).digest('hex'),root=new URL('../../../',NINTH_ORIGINAL_URL),raw=fs.readFileSync(new URL('./dependency-proof.json',NINTH_ORIGINAL_URL));assert.equal(sha(raw),'a2cf2b9aaf0a47904a2cdc5c83b47db52cd5581ae7b1bb673f71e22eafcc7e57','seventh exact dependency evidence changed');
export const proof=JSON.parse(raw);assert.equal(proof.schemaVersion,1);assert.equal(proof.modelTransitions.length,8);assert.equal(proof.legacyDestinationMigrations.length,46);assert.equal(proof.frameworkWitnessMigrations.length,3);
for(const [p,h]of Object.entries(proof.originalDataFiles))assert.equal(sha(fs.readFileSync(new URL(p,root))),h,'original data evidence changed '+p);
const get=(E,key)=>{const at=key.lastIndexOf('#'),id=key.slice(0,at),q=key.slice(at+1),e=E.get(id);assert.ok(e,'missing '+id);const it=e.items.find((it,i)=>String(it.id??i)===q);assert.ok(it,'missing '+key);return it;};
const leaf=(e,p)=>p.reduce((x,k)=>x[k],e),set=(e,p,v)=>{p.slice(0,-1).reduce((x,k)=>x[k],e)[p.at(-1)]=v;};
for(const r of [...proof.modelTransitions,...proof.frameworkTransitions]){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);}
export function composeSeventhEntry(old){const next=structuredClone(old);for(const r of proof.modelTransitions.filter(x=>x.entryId===old.id)){assert.equal(leaf(next,r.path),r.before,'exact full old object before seventh composition');set(next,r.path,r.after);}return ninthEntry(next);}
export function assertModelTransitions(E){for(const old of proof.modelBeforeEntries)assert.deepEqual(E.get(old.id),composeSeventhEntry(old),'exact all old model6/model7 full objects');const r=proof.releaseSourceRecord,actual=get(E,'ai-模型与评测-6#2').a,fold=x=>x.match(/<details class="qa-variants">[\s\S]*?<\/details>/)?.[0],lis=x=>[...fold(x).matchAll(/<li>([\s\S]*?)<\/li>/g)].map(m=>m[1]);assert.equal(lis(r.before).length,17);assert.equal(lis(actual).length,17);assert.deepEqual(lis(actual).sort(),lis(r.before).sort(),'all original seventeen full variant innerHTML preserved');return true;}
export function composeSeventhQuestion(key,old){const at=key.lastIndexOf('#'),id=key.slice(0,at),index=Number(key.slice(at+1)),next=structuredClone(old);for(const r of proof.modelTransitions.filter(x=>x.entryId===id&&x.path[1]===index)){assert.equal(next[r.path[2]],r.before);next[r.path[2]]=r.after;}return ninthKeyQuestion(key,next);}
export function referenceSeventhItem(key,current){if(!['ai-模型与评测-6#2','ai-模型与评测-6#4'].includes(key))return current;const index=Number(key.split('#')[1]),old=proof.modelBeforeEntries.find(e=>e.id==='ai-模型与评测-6').items[index];assert.deepEqual(current,composeSeventhQuestion(key,old));return old;}
export function approvedSeventhLeaf(oldRecord){const r=proof.modelTransitions.find(x=>x.entryId===oldRecord.entryId&&JSON.stringify(x.path)===JSON.stringify(oldRecord.path));if(!r)return oldRecord.after;assert.equal(oldRecord.after,r.before);assert.equal(oldRecord.afterSha256,r.beforeSha256);return r.after;}
function readPointer(o,p){for(const k of p.split('/').slice(1))o=o[k];return o;}
const oldMap=JSON.parse(fs.readFileSync(new URL('tests/fixtures/model-contracts/preservation-map.json',root))),release=proof.releaseSourceRecord,bs=[...release.before.matchAll(/<(p|h[1-6]|li|th|td|summary)\b[^>]*>[\s\S]*?<\/\1>/g)].map(m=>m[0]);
for(const m of proof.legacyDestinationMigrations){assert.deepEqual(readPointer(oldMap,m.pointer),m.before);assert.equal(m.before.html,bs[m.sourceCurrentBlockIndex]);assert.equal(m.before.html,m.releaseSourceRow.sourceHtml);assert.equal(sha(m.before.html),m.before.sha256);assert.equal(m.releaseSourceRow.sourceSha256,m.before.sha256);const expanded=m.releaseSourceRow.destinations.flatMap(d=>(d.fragments||[d.html]).map(html=>({key:d.stableReviewKey,html})));assert.deepEqual(m.afterDestinations.map(d=>({key:d.stableReviewKey,html:d.html})),expanded);for(const d of m.afterDestinations){assert.equal(sha(d.html),d.sha256);assert.match(d.html,/<(?:p|li)\b/,'migration requires substantive prose');assert.ok(d.html.replace(/<[^>]*>/g,'').length>=40,'title or bare link cannot discharge a legacy condition');}}
assert.equal(new Set(proof.legacyDestinationMigrations.map(m=>m.before.stableReviewKey+'|'+m.before.sha256)).size,22);
export function assertLegacyDestination(d,E){assert.equal(sha(d.html),d.sha256);const rows=proof.legacyDestinationMigrations.filter(m=>m.before.stableReviewKey===d.stableReviewKey&&m.before.html===d.html);if(!rows.length){assert.ok(ninthKeyIncludes(E,d.stableReviewKey,d.html),'unchanged old destination lost '+d.stableReviewKey);return true;}for(const row of rows){assert.deepEqual(row.before,d);for(const next of row.afterDestinations)assert.ok(ninthKeyIncludes(E,next.stableReviewKey,next.html),'transitive substantive condition lost '+next.stableReviewKey);}return true;}
export function assertFrameworkDestination(d,E){const key=d.entryId+'#'+d.itemIndex,row=proof.frameworkWitnessMigrations.find(x=>x.oldKey===key&&x.oldHtml===d.html);if(!row)return false;assert.equal(d.sha256,row.oldSha256);assert.equal(sha(row.oldHtml),row.oldSha256);assert.equal(row.sourceRow.html,row.oldHtml);assert.equal(row.sourceRow.sha256,row.oldSha256);for(const review of proof.frameworkConditionReviews)for(const w of review.witnesses){assert.equal(sha(w.html),w.sha256);assert.ok(ninthKeyIncludes(E,w.key,w.html),'old framework clause lost: '+review.condition);}assert.deepEqual(E.get('ai-agent-6'),eighthEntry(proof.frameworkAfterEntry),'all old17 objects plus exact8 questions and12 leaves and approved eighth transitions');const expected=structuredClone(proof.frameworkBeforeEntry);assert.equal(expected.items.length,17);for(const r of proof.frameworkTransitions.filter(r=>r.entryId===expected.id)){assert.equal(leaf(expected,r.path),r.before);set(expected,r.path,r.after);}for(const a of proof.frameworkAppends.appends){assert.equal(a.index,expected.items.length);assert.equal(sha(JSON.stringify(a.expectedItem)),a.expectedItemSha256);expected.items.push(a.expectedItem);}Object.assign(expected,proof.frameworkAppends.metadataAfter);assert.deepEqual(expected,proof.frameworkAfterEntry);assert.equal(expected.items.length,25);for(const target of row.sourceRow.destinations){const actual=get(E,target.entryId+'#'+target.questionId);assert.equal(sha(actual.a),ninthKeyHash(E,target.entryId+'#'+target.questionId,target.bodySha256));assert.equal(target.snippets.length,target.snippetSha256.length);for(const [i,s]of target.snippets.entries()){assert.equal(sha(s),target.snippetSha256[i]);assert.match(s,/<p\b/);assert.ok(ninthKeyIncludes(E,target.entryId+'#'+target.questionId,s),'framework migrated condition lost');}}return true;}
export function appendProviderQuestion(expected){if(expected.id!=='ai-模型与评测-2')return expected;assert.deepEqual(expected,proof.providerBeforeEntry,'all13 pre-seventh full model2 objects, including earlier workflow and metrics');assert.equal(expected.items.length,13);const a=proof.providerAppend;assert.equal(a.index,13);assert.equal(a.id,'q-model-provider-version-selection');assert.equal(sha(JSON.stringify(a.expectedItem)),a.expectedItemSha256);const next=structuredClone(expected);next.items.push(a.expectedItem);Object.assign(next,proof.providerMetadataAfter);assert.equal(next.items.length,14);assert.equal(next.number,'14 问');return ninthEntry(next);}
const codeRaw=fs.readFileSync(new URL('./original-code-transition-proof.json',NINTH_ORIGINAL_URL));assert.equal(sha(codeRaw),'52e92b75cbbbe80d569dcb911c8d210c9a2ea33027af6f180eb3437d9adc5e88');const code=JSON.parse(codeRaw);assert.equal(code.transitions.length,2);
export function assertReviewedOriginalFile(p,h){const c=code.transitions.find(x=>x.target===p);if(!c){assert.equal(sha(fs.readFileSync(new URL(p,root))),eighthSourceHash(p,h),'original fixture changed '+p);return;}assert.equal(c.beforeSha256,h);assert.equal(sha(c.before),h);let s=c.before;for(const e of c.edits){assert.equal(s.split(e.before).length,2,'exact sole approved code span');s=s.replace(e.before,e.after);}assert.equal(s,c.after);assert.equal(sha(s),c.afterSha256);assert.equal(fs.readFileSync(new URL(p,root),'utf8'),eighthSourceText(p,c.after),'only approved original verifier/wrapper code evolution');}
